(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.03-t*0.4)*8 + Math.cos(my*0.025+t*0.3)*6;
  const w2y = Math.cos(my*0.028+t*0.35)*8 + Math.sin(mx*0.022-t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*40, 0.085, 1.8]
  ];
  let aS=0, iS=0, hrm=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hrm += Math.sin(d*f*1.3-t*sp*0.8+2.0)*0.5;
  }
  const act=aS/8, inh=iS/8, hm=hrm/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08+sy*0.06-t*1.3)+Math.sin(sx*0.07-sy*0.09+t*1.5))/4;
  const bg3=(Math.sin(sx*0.16+sy*0.12+t*2.5)+Math.sin(sx*0.14-sy*0.18-t*2))/8;
  const bg=bg1+bg2+bg3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2=Math.sin(dist*0.07-ang*5+t*0.8)*0.2;
  const spiral=sp1+sp2;
  const raw=act-inh*0.7+bg*0.3+spiral+hm*0.2;
  const reaction=Math.tanh(raw*2.2);
  const feedback=Math.tanh(reaction*1.5+Math.sin(reaction*Math.PI*2)*0.3);
  const cX=sx*0.15, cY=sy*0.15;
  const cell=Math.tanh((Math.sin(cX)*Math.sin(cY)+Math.sin((cX+cY)*0.7+t)*0.5+Math.sin(cX*2.1-cY*1.7+t*0.7)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+sy*0.2-t*3)*Math.sin(sx*0.25-sy*0.35+t*2.5)*0.15;
  const blend=feedback*0.6+cell*0.25+micro*0.15, v=blend*0.5+0.5;
  const pal=[[6,12,42],[12,45,78],[18,95,115],[35,155,130],[120,185,100],[210,190,60],[225,140,55],[200,85,75],[160,50,80],[100,30,65],[50,18,55],[6,12,42]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(feedback*Math.PI)*0.2;
  const edge=Math.abs(feedback)>0.7?1.15:1.0;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.25;
  const chr=reaction*0.02;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig*(1+chr))|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig*(1-chr))|0
  ];
}
